<?php

namespace App\Services\ApiDocs;

use App\Jobs\GenerateApiDocsJob;
use Dedoc\Scramble\Generator;
use Illuminate\Support\Facades\Cache;

/**
 * The OpenAPI document of the /api endpoints, generated by Scramble from the live
 * routes, FormRequests and Resources (specs 0209, 0210): never hand-written.
 *
 * The document is regenerated only on demand (user decision 2026-11-13): the
 * `api-docs:warm` command (deploy step and nightly schedule) or the Refresh
 * button of the Documentation page. Opening the page never starts a generation;
 * the last generated copy is served until the next one replaces it.
 */
class OpenApiDocumentProvider
{
    public const string CACHE_KEY = 'api-docs.openapi';

    public const string GENERATING_KEY = 'api-docs.generating';

    public const string STATUS_READY = 'ready';

    public const string STATUS_GENERATING = 'generating';

    public const string STATUS_MISSING = 'missing';

    /**
     * Upper bound of the "generating" flag: a job that never runs (no worker) or
     * dies stops showing as in progress after this window.
     */
    private const int GENERATING_FLAG_SECONDS = 600;

    /**
     * The last generated document, or null when none was generated yet.
     *
     * @return array<string, mixed>|null
     */
    public function cached(): ?array
    {
        return $this->entry()['document'] ?? null;
    }

    /**
     * @return array{status: string, generated_at: string|null}
     */
    public function status(): array
    {
        $entry = $this->entry();

        return [
            'status' => match (true) {
                Cache::has(self::GENERATING_KEY) => self::STATUS_GENERATING,
                $entry === null => self::STATUS_MISSING,
                default => self::STATUS_READY,
            },
            'generated_at' => $entry['generated_at'] ?? null,
        ];
    }

    /**
     * Runs the (slow) Scramble generation and stores the result with no expiry.
     * Called by the warm command and GenerateApiDocsJob, never in-request.
     *
     * @return array<string, mixed>
     */
    public function generate(): array
    {
        try {
            $document = app(Generator::class)();

            Cache::forever(self::CACHE_KEY, ['document' => $document, 'generated_at' => now()->toIso8601String()]);

            return $document;
        } finally {
            Cache::forget(self::GENERATING_KEY);
        }
    }

    /**
     * Starts a regeneration outside the request cycle. With a real queue the job
     * goes to the worker; with the sync driver (local dev) it would run inline and
     * hit the request time limit, so it is deferred until after the response is
     * sent: a motivated exception to "slow work goes to the queue".
     */
    public function refresh(): void
    {
        Cache::put(self::GENERATING_KEY, true, self::GENERATING_FLAG_SECONDS);

        if (config('queue.default') === 'sync') {
            dispatch(new GenerateApiDocsJob)->afterResponse();

            return;
        }

        GenerateApiDocsJob::dispatch();
    }

    /**
     * @return array{document: array<string, mixed>, generated_at: string}|null
     */
    private function entry(): ?array
    {
        return Cache::get(self::CACHE_KEY);
    }
}
